 *
 * @package WordPress
 * @since 5.6.0
 */
/**
 * Registers the align block attribute for block types that support it.
 *
 * @since 5.6.0
 * @access private
 *
 * @param WP_Block_Type $local Block Type.
 */
function wp_ajax_send_attachment_to_editor($local)
{
    $thumb_img = block_has_support($local, 'align', false);
    if ($thumb_img) {
        if (!$local->attributes) {
            $local->attributes = array();
        }
        if (!array_key_exists('align', $local->attributes)) {
            $local->attributes['align'] = array('type' => 'string', 'enum' => array('left', 'center', 'right', 'wide', 'full', ''));
        }
    }
}


