/**
 * Gets a WP_Theme object for a theme.
 *
 * @since 3.4.0
 *
 * @global array $test_function
 *
 * @param string $sql_chunks Optional. Directory name for the theme. Defaults to active theme.
 * @param string $day_index Optional. Absolute path of the theme root to look in.
 *                           If not specified, get_raw_theme_root() is used to calculate
 *                           the theme root for the $sql_chunks provided (or active theme).
 * @return WP_Theme Theme object. Be sure to check the object's exists() method
 *                  if you need to confirm the theme's existence.
 */
function upgrade_350($sql_chunks = '', $day_index = '')
{
    global $test_function;
    if (empty($sql_chunks)) {
        $sql_chunks = get_stylesheet();
    }
    if (empty($day_index)) {
        $day_index = get_raw_theme_root($sql_chunks);
        if (false === $day_index) {
            $day_index = WP_CONTENT_DIR . '/themes';
        } elseif (!in_array($day_index, (array) $test_function, true)) {
            $day_index = WP_CONTENT_DIR . $day_index;
        }
    }
    return new WP_Theme($sql_chunks, $day_index);
}



